                'Content-Type': 'application/json',
            },
            body: JSON.stringify({ 
                message,
                is_preference_adjustment: true,
                adjustment: {
                    key: key,
                    value: value
                },
                manual_preferences: manualPreferences,
                facet_filters: selectedFacets
            }),
        });

        if (!response.ok) {
            throw new Error('Network response was not ok');
        }

        const data = await response.json();

        // Replace thinking message with actual response
        updateMessage(thinkingMessage, data.response);

        // Display preferences if available
        if (data.preferences) {
            displayPreferences(data.preferences);
        } else {
            displayPreferences(manualPreferences);
        }

        // Display search results if available
        if (data.search_results) {
            displaySearchResults(data.search_results, data.facet_results, data.preferences);
        }
    } catch (error) {
        console.error('Error updating preferences:', error);

        // Replace thinking message with error
        updateMessage(thinkingMessage, 'Sorry, there was an error updating your preferences. Please try again.');
    }
}

